import csv
import io
import re


_NUMBER = re.compile(
    r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?"
)


def _is_number(value):
    return _NUMBER.fullmatch(value.strip()) is not None


def _find_header(records):
    candidate = None
    first_pair = None
    first_nonblank = None

    for index, row in enumerate(records):
        if first_nonblank is None and any(value.strip() for value in row):
            first_nonblank = index
        if len(row) != 2 or not any(value.strip() for value in row):
            continue
        if first_pair is None:
            first_pair = index
        if all(_is_number(value) for value in row):
            if candidate is not None:
                return candidate
            if first_pair < index:
                return first_pair
            if first_nonblank is not None and first_nonblank < index:
                return first_nonblank
            return None
        if all(value.strip() and not _is_number(value) for value in row):
            candidate = index

    if first_pair is not None:
        return first_pair
    return first_nonblank


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    with io.StringIO(raw_csv, newline="") as source:
        records = list(csv.reader(source, delimiter=",", quotechar='"',
                                  doublequote=True))

    if not records:
        return {"columns": [], "rows": []}

    header = _find_header(records)
    if header is None:
        columns = ["column_1", "column_2"]
        rows = records
    else:
        columns = records[header][:]
        rows = records[header + 1:]

    width = max(2, len(columns), max((len(row) for row in rows), default=0))
    used = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used:
            columns.append(name)
            used.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
